93	///   unquoted fails by name rather than running nothing.
94	/// - Elements keep their text verbatim apart from the quotes, so a
95	///   command line with its own spaces and dashes is one element.
96	pub fn toml_get_list(
97	    map: &HashMap<String, String>,
98	    key: &str,
99	) -> Result<Option<Vec<String>>, String> {
100	    let Some(raw) = toml_get(map, key) else {
