106	/// Parse a TOML array of double-quoted strings from its literal
107	/// text, `label` naming the value in any error.
108	///
109	/// The one place the array dialect is defined: `toml_get_list`
110	/// reads a loaded value through it, and the config model renders a
111	/// `str-list` through it, so a value that loads is a value the
112	/// model can show.
113	pub fn parse_array(raw: &str, label: &str) -> Result<Vec<String>, String> {
114	    let Some(body) = raw
115	        .trim()
116	        .strip_prefix('[')
117	        .and_then(|s| s.strip_suffix(']'))
118	    else {
119	        return Err(format!(
120	            "{label}: expected an array like [\"a\", \"b\"], got {raw}"
121	        ));
122	    };
123	    let mut items = Vec::new();
124	    let mut rest = body.trim();
125	    while !rest.is_empty() {
126	        let Some(after_open) = rest.strip_prefix('"') else {
127	            return Err(format!(
128	                "{label}: array elements must be double-quoted strings, at: {rest}"
129	            ));
130	        };
131	        let Some(close) = after_open.find('"') else {
132	            return Err(format!("{label}: unterminated string in array: {raw}"));
133	        };
134	        items.push(after_open[..close].to_string());
135	        rest = after_open[close + 1..].trim();
136	        if let Some(r) = rest.strip_prefix(',') {
137	            rest = r.trim();
138	        } else if !rest.is_empty() {
139	            return Err(format!(
140	                "{label}: expected `,` between array elements, at: {rest}"
141	            ));
142	        }
143	    }
144	    Ok(items)
145	}
