    let fx = crate::test_helpers::Fixture::new("dual-config");

    let work_cfg = std::fs::read_to_string(fx.work.join(".vc-config.toml"))
        .expect("read work .vc-config.toml");
    assert!(work_cfg.contains("work = \".\""), "work work = \".\"");
