1	//! The `validate-anchors` subcommand: check a markdown record's
2	//! own links, so a dead anchor is found by a command rather than
3	//! by a reader.
4	//!
5	//! Three checks, all same-file:
6	//!
7	//! - every `](#slug)` link and `[N]: #slug` definition resolves to
8	//!   a heading in the same file
9	//! - every `[[N]]` citation has an `[N]:` definition, and every
10	//!   definition is cited
11	//! - no two headings slug to the same anchor, which markdown
12	//!   silently disambiguates, so the second link lands on the first
13	//!   heading
14	//!
15	//! Cross-file targets (`](other.md#slug)`, `[N]: /notes/x.md#y`)
16	//! are recognized and skipped: resolving one means slugging another
17	//! file's headings, which is its own step (see the `## Todo` entry
18	//! **Reference defs: go file-relative, with anchors**).
19	//!
20	//! Fenced code and code spans are excluded throughout. A `[[N]]` in
21	//! a code span is a quoted identifier rather than a citation, and a
22	//! `#` line inside a fence is code rather than a heading.
23	
24	use std::collections::{BTreeMap, BTreeSet};
25	use std::path::{Path, PathBuf};
26	
27	use clap::Args;
28	use log::{debug, info, warn};
29	
30	use crate::context::Context;
31	use crate::subcommand::SubcommandRunner;
32	
33	/// Clap-derived args for `validate-anchors`.
34	#[derive(Args, Debug)]
35	pub struct ValidateAnchorsArgs {
36	    /// Markdown files to check. Default: every tracked `.md` in
37	    /// the workspace, excluding the agent repo and build output.
38	    #[arg(value_name = "FILE")]
39	    pub files: Vec<PathBuf>,
40	}
41	
42	/// Inputs to the validate-anchors op, flat, owned, clap-free.
43	pub struct ValidateAnchorsParams {
44	    pub files: Vec<PathBuf>,
45	}
46	
47	impl From<&ValidateAnchorsArgs> for ValidateAnchorsParams {
48	    /// Convert clap-derived args into the flat params (total).
49	    fn from(a: &ValidateAnchorsArgs) -> Self {
50	        Self {
51	            files: a.files.clone(),
52	        }
53	    }
54	}
55	
56	impl SubcommandRunner for ValidateAnchorsArgs {
57	    type Params = ValidateAnchorsParams;
58	
59	    /// Delegate to the `From<&ValidateAnchorsArgs>` impl (total).
60	    fn to_params(&self) -> Result<Self::Params, String> {
61	        Ok(ValidateAnchorsParams::from(self))
62	    }
63	
64	    /// Run the `validate_anchors` op.
65	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
66	        validate_anchors(ctx, params)
67	    }
68	}
69	
70	/// One problem found in one file.
71	#[derive(Debug, PartialEq, Eq)]
72	pub struct Finding {
73	    /// 1-based line the problem is on, or 0 when the problem is
74	    /// the file's as a whole (an uncited definition names its own
75	    /// line, so every finding today has one).
76	    pub line: usize,
77	    pub message: String,
78	}
79	
80	/// A heading's GitHub anchor.
81	///
82	/// The algorithm [Markdown anchor
83	/// links](../agent-data/notes.md#markdown-anchor-links) documents:
84	/// lowercase, drop every character that is not alphanumeric, a
85	/// hyphen, or an underscore, and map each remaining space to one
86	/// hyphen. Adjacent spaces are not collapsed, so `a + b` slugs to
87	/// `a--b` while `a: b` slugs to `a-b`.
88	pub fn anchor_slug(heading: &str) -> String {
89	    heading
90	        .chars()
91	        .filter_map(|c| match c {
92	            'a'..='z' | '0'..='9' | '-' | '_' => Some(c),
93	            'A'..='Z' => Some(c.to_ascii_lowercase()),
94	            ' ' => Some('-'),
95	            _ => None,
96	        })
97	        .collect()
98	}
99	
100	/// Blank out code spans in one line, keeping its length so column
101	/// arithmetic still lines up.
102	///
103	/// Backticks pair left to right. An unpaired backtick opens a span
104	/// that runs to the end of the line, which is the reading that
105	/// errs toward ignoring text rather than inventing a citation in
106	/// it.
107	fn blank_code_spans(line: &str) -> String {
108	    let mut out = String::with_capacity(line.len());
109	    let mut in_span = false;
110	    for c in line.chars() {
111	        if c == '`' {
112	            in_span = !in_span;
113	            out.push(' ');
114	        } else if in_span {
115	            out.push(' ');
116	        } else {
117	            out.push(c);
118	        }
119	    }
120	    out
121	}
122	
123	/// The file's lines with fenced blocks and code spans blanked, so
124	/// every later scan sees prose only.
125	fn prose_lines(content: &str) -> Vec<String> {
126	    let mut out = Vec::new();
127	    let mut in_fence = false;
128	    for line in content.lines() {
129	        if line.trim_start().starts_with("```") {
130	            in_fence = !in_fence;
131	            out.push(String::new());
132	            continue;
133	        }
134	        if in_fence {
135	            out.push(String::new());
136	            continue;
137	        }
138	        out.push(blank_code_spans(line));
139	    }
140	    out
141	}
142	
143	/// Collect `(slug, line)` for every heading, in document order.
144	fn headings(lines: &[String]) -> Vec<(String, usize)> {
145	    let mut out = Vec::new();
146	    for (i, line) in lines.iter().enumerate() {
147	        let Some(rest) = line.strip_prefix('#') else {
148	            continue;
149	        };
150	        let text = rest.trim_start_matches('#');
151	        // `#foo` is not a heading, `# foo` is.
152	        if !text.starts_with(' ') {
153	            continue;
154	        }
155	        out.push((anchor_slug(text.trim()), i + 1));
156	    }
157	    out
158	}
159	
160	/// Every same-file anchor target: `](#slug)` inline links and
161	/// `[N]: #slug` definitions, as `(slug, line)`.
162	///
163	/// A target naming another file is skipped here, since resolving
164	/// it is the cross-file check this rung leaves out.
165	fn anchor_targets(lines: &[String]) -> Vec<(String, usize)> {
166	    let mut out = Vec::new();
167	    for (i, line) in lines.iter().enumerate() {
168	        for (idx, _) in line.match_indices("](#") {
169	            let rest = &line[idx + 3..];
170	            if let Some(end) = rest.find(')') {
171	                out.push((rest[..end].to_string(), i + 1));
172	            }
173	        }
174	        if let Some(rest) = ref_def(line)
175	            && let Some(slug) = rest.strip_prefix('#')
176	        {
177	            out.push((slug.trim().to_string(), i + 1));
178	        }
179	    }
180	    out
181	}
182	
183	/// The target of a `[N]: <target>` definition line, if the line is
184	/// one.
185	fn ref_def(line: &str) -> Option<&str> {
186	    let rest = line.trim_start().strip_prefix('[')?;
187	    let (num, rest) = rest.split_once(']')?;
188	    if num.is_empty() || !num.chars().all(|c| c.is_ascii_digit()) {
189	        return None;
190	    }
191	    Some(rest.strip_prefix(':')?.trim())
192	}
193	
194	/// The reference number a `[N]: ...` definition line declares.
195	fn ref_def_number(line: &str) -> Option<u32> {
196	    let rest = line.trim_start().strip_prefix('[')?;
197	    let (num, rest) = rest.split_once(']')?;
198	    rest.strip_prefix(':')?;
199	    num.parse().ok()
200	}
201	
202	/// Every reference number the line uses, in either of the two
203	/// forms that use one.
204	///
205	/// - `[[N]]`, the notes convention's citation, doubled so the
206	///   brackets render.
207	/// - `[text][N]`, a markdown reference link, which is how a ladder
208	///   rung names its own subsection.
209	///
210	/// Both are uses, so a definition either form reaches is cited.
211	fn citations(line: &str) -> Vec<u32> {
212	    let mut out = Vec::new();
213	    for (idx, _) in line.match_indices("[[") {
214	        let rest = &line[idx + 2..];
215	        if let Some(end) = rest.find("]]")
216	            && let Ok(n) = rest[..end].parse::<u32>()
217	        {
